import{_ as i}from"./chunks/15-ai-agents.Ct28VXVn.js";import{_ as s,o as t,c as a,a3 as n}from"./chunks/framework.BGhsAJMQ.js";const g=JSON.parse('{"title":"Configure LLM review","description":"","frontmatter":{},"headers":[],"relativePath":"guide/llm-review.md","filePath":"guide/llm-review.md","lastUpdated":1793985812000}'),o={name:"guide/llm-review.md"};function r(l,e,d,p,h,c){return t(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="configure-llm-review" tabindex="-1">Configure LLM review <a class="header-anchor" href="#configure-llm-review" aria-label="Permalink to &quot;Configure LLM review&quot;">​</a></h1><p>If you use <strong>AI Agents</strong> to send prompts to coding agents, configure an LLM provider after <a href="./install-hub">installing the Hub</a>. Prompt review is <strong>on and mandatory by default</strong>: without a configured reviewer, every prompt is rejected. Provider errors, timeouts or invalid review responses also refuse delivery (fail-closed).</p><p>This step is not required for file browsing or previews. AI Agents status, output reads and allowlisted keys remain available without a reviewer; keys are not LLM-reviewed. The reviewer receives the prompt and recent output from the target window, so choose a provider appropriate for that data.</p><h2 id="run-the-setup-wizard" tabindex="-1">Run the setup wizard <a class="header-anchor" href="#run-the-setup-wizard" aria-label="Permalink to &quot;Run the setup wizard&quot;">​</a></h2><p>From the Hub package directory, after <code>./bin/hub --init-config</code> has created <code>config/hub.json</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/hub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --init-llm</span></span></code></pre></div><p>For a different existing configuration file:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/hub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --init-llm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/hub.json</span></span></code></pre></div><ol><li>Choose a provider preset or <strong>Custom</strong>; confirm its base URL, optional endpoint path and provider name.</li><li>Choose an environment-variable API key (recommended) or an inline key.</li><li>Select a model returned by the provider or enter its identifier manually.</li><li>The wizard tests chat, JSON output and a thinking-enabled tool call. If a test fails, it asks whether to save anyway; resolve provider errors before relying on review.</li><li>Choose to use this provider for <strong>AI Agents prompt review</strong>.</li></ol><p>The wizard preserves other Hub settings. With environment-variable storage, if the variable is missing, it asks for a key for its tests; that testing key is <strong>not saved</strong>. Supply the variable to the running Hub too, then restart the Hub to apply the configuration. The wizard does not disable review.</p><h2 id="configure-hub-json" tabindex="-1">Configure <code>hub.json</code> <a class="header-anchor" href="#configure-hub-json" aria-label="Permalink to &quot;Configure \`hub.json\`&quot;">​</a></h2><p>The wizard writes a named provider and a review reference. You can also merge these fields into the existing <code>hub.json</code>; <strong>do not replace your authentication settings</strong>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;llm_providers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;deepseek&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;protocol&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;chat_completions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;base_url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://api.deepseek.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;model&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deepseek-flash&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;api_key_env&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;DEEPSEEK_API_KEY&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;timeout_secs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;prompt_review&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;provider&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deepseek&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Provider names start with an ASCII letter or digit and contain only ASCII letters, digits, <code>_</code> or <code>-</code>, up to 64 characters. <code>prompt_review.provider</code> must name an entry in <code>llm_providers</code>; the reference can also override <code>model</code> and <code>timeout_secs</code>. Legacy inline provider configuration under <code>prompt_review</code> remains supported.</p><table tabindex="0"><thead><tr><th>Provider field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>protocol</code></td><td><code>chat_completions</code>, <code>responses</code> or <code>messages</code></td></tr><tr><td><code>base_url</code></td><td>Provider base URL; HTTPS is required except for loopback hosts. No credentials, query or fragment in the URL.</td></tr><tr><td><code>path</code></td><td>Optional endpoint path override; must start with <code>/</code>, with no query, fragment, <code>..</code> or whitespace.</td></tr><tr><td><code>model</code></td><td>Model identifier to use for review</td></tr><tr><td><code>api_key_env</code></td><td>Name of the environment variable containing the API key</td></tr><tr><td><code>api_key</code></td><td>Alternative inline key in the private config; prefer <code>api_key_env</code></td></tr><tr><td><code>timeout_secs</code></td><td>Default 20 seconds. The provider client clamps to 1–300 seconds; Hub prompt review clamps to 1–60 seconds.</td></tr></tbody></table><p>Default endpoint paths are <code>/chat/completions</code>, <code>/responses</code> and <code>/anthropic/v1/messages</code>, respectively. For the official Anthropic API, use <code>base_url: &quot;https://api.anthropic.com&quot;</code> and <code>path: &quot;/v1/messages&quot;</code> with protocol <code>messages</code> and an appropriate model/key.</p><h2 id="supply-the-api-key-to-the-hub-service" tabindex="-1">Supply the API key to the Hub service <a class="header-anchor" href="#supply-the-api-key-to-the-hub-service" aria-label="Permalink to &quot;Supply the API key to the Hub service&quot;">​</a></h2><p>An exported variable in your interactive shell is not automatically available to systemd. For the <a href="./install-hub#systemd-example-optional">systemd deployment</a>, add an <code>EnvironmentFile=</code> entry under <code>[Service]</code> in the Hub unit or a drop-in:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Service]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">EnvironmentFile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/etc/filebox-hub/llm.env</span></span></code></pre></div><p>Create that file with the real key (replace the placeholder), restrict it to the service administrator, and keep it out of version control:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DEEPSEEK_API_KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=replace-with-your-provider-key</span></span></code></pre></div><p>For a system service, a root-owned file with mode <code>0600</code> is appropriate. After changing the unit, reload systemd and restart the service (replace <code>filebox-hub.service</code> with your unit name):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daemon-reload</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> filebox-hub.service</span></span></code></pre></div><p>For manual or container deployments, pass the same variable to the Hub process before starting it. A missing or empty key for a configured review provider fails configuration validation at startup.</p><h2 id="verify-review-is-configured" tabindex="-1">Verify review is configured <a class="header-anchor" href="#verify-review-is-configured" aria-label="Permalink to &quot;Verify review is configured&quot;">​</a></h2><p>Open <strong>AI Agents</strong>, select a window, and check for <strong>Reviewed by deepseek-flash</strong> (or your configured model). Missing review configuration instead shows <strong>Prompts disabled: configure prompt_review in hub.json</strong>, or <strong>Prompt review not configured</strong> in compact/mobile layouts.</p><p><img src="`+i+'" alt="AI Agents with prompt review configured"></p><p>The model label confirms configuration, not provider availability. Send a harmless prompt appropriate for the selected coding agent to check delivery. If review fails, the prompt is not forwarded and the draft stays available; check the service&#39;s API-key environment, endpoint, model and provider availability before retrying. See <a href="/filebox/features/ai-agents">AI Agents</a> for usage and review boundaries.</p><h2 id="explicitly-disable-review" tabindex="-1">Explicitly disable review <a class="header-anchor" href="#explicitly-disable-review" aria-label="Permalink to &quot;Explicitly disable review&quot;">​</a></h2><p>Only if you intend to forward prompts <strong>without LLM review</strong>, start the Hub with <code>FILEBOX_HUB_PROMPT_REVIEW_ENABLED=0</code> (or <code>false</code>). With systemd, add this to the service&#39;s <code>[Service]</code> section, reload systemd and restart the Hub:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Environment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FILEBOX_HUB_PROMPT_REVIEW_ENABLED</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=0</span></span></code></pre></div><p>The setting is read once at startup. Unset, <code>1</code>, <code>true</code> or invalid values keep review mandatory. The AI Agents view shows <strong>Prompt review off</strong> when disabled; removing <code>prompt_review</code> from JSON alone does not disable review.</p><p>Next: <a href="./install-agent">Install Agent</a></p>',33)])])}const v=s(o,[["render",r]]);export{g as __pageData,v as default};
